import{_ as s,o as t,c as n,ah as i}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Enseignement supérieur : filières, maquettes et promotions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/enseignement-superieur.md","filePath":"src/guide/admin/enseignement-superieur.md"}'),r={name:"guide/admin/enseignement-superieur.md"};function a(o,e,l,u,d,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="enseignement-superieur-filieres-maquettes-et-promotions" tabindex="-1">Enseignement supérieur : filières, maquettes et promotions <a class="header-anchor" href="#enseignement-superieur-filieres-maquettes-et-promotions" aria-label="Permalink to &quot;Enseignement supérieur : filières, maquettes et promotions&quot;">​</a></h1><p>Si votre établissement délivre des diplômes du supérieur (licence, master, doctorat), ERA organise ses formations selon le système LMD : des <strong>filières</strong>, enseignées à certains <strong>niveaux</strong> (L1, L2, L3…), dont la <strong>maquette</strong> répartit les crédits en <strong>unités d&#39;enseignement (UE)</strong> composées d&#39;<strong>éléments constitutifs (EC)</strong>.</p><p>L&#39;espace s&#39;ouvre par <strong>Supérieur → Filières</strong>. Il apparaît si votre licence comprend l&#39;enseignement supérieur.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><p>Les filières vivent dans un <strong>département de type « Université »</strong>, avec ses niveaux. Créez-les d&#39;abord dans le paramétrage scolaire :</p><ol><li><strong>Paramétrage → Départements</strong> : un département de type <em>Université</em>, par exemple « Faculté des sciences ».</li><li><strong>Paramétrage → Niveaux</strong> : ses niveaux, dans l&#39;ordre (L1, L2, L3, M1, M2).</li></ol><h2 id="creer-une-filiere" tabindex="-1">Créer une filière <a class="header-anchor" href="#creer-une-filiere" aria-label="Permalink to &quot;Créer une filière&quot;">​</a></h2><p>Depuis <strong>Filières</strong>, le bouton <strong>Nouvelle filière</strong> demande :</p><ul><li>le <strong>département</strong> et le <strong>nom</strong> de la filière, avec un code facultatif (« INFO ») ;</li><li>le <strong>diplôme</strong> : licence, master ou doctorat ;</li><li>le <strong>rythme</strong> : semestriel par défaut, trimestriel ou annuel ;</li><li>les <strong>crédits par an</strong>, 60 par défaut. Ils se répartissent à parts égales entre les périodes : 30 par semestre en rythme semestriel ;</li><li>les <strong>niveaux enseignés</strong> : L1 à L3 pour une licence, L3 seule pour une licence professionnelle ;</li><li>ses <strong>responsables de filière</strong>.</li></ul><p>Le rythme et le département ne changent plus une fois la maquette commencée, et une filière qui a déjà une maquette ou des promotions ne peut pas être supprimée.</p><h2 id="les-responsables-de-filiere" tabindex="-1">Les responsables de filière <a class="header-anchor" href="#les-responsables-de-filiere" aria-label="Permalink to &quot;Les responsables de filière&quot;">​</a></h2><p>Un responsable de filière tient la maquette de <strong>sa</strong> filière, et de celle-là seulement. Ce n&#39;est pas un rôle à part : un enseignant ou un membre du personnel garde son rôle habituel et reçoit en plus l&#39;espace <strong>Supérieur</strong>, limité aux filières dont il a la charge. La création et la modification des filières restent réservées à l&#39;administrateur.</p><h2 id="construire-la-maquette" tabindex="-1">Construire la maquette <a class="header-anchor" href="#construire-la-maquette" aria-label="Permalink to &quot;Construire la maquette&quot;">​</a></h2><p>Le bouton <strong>Maquette</strong> d&#39;une filière ouvre sa maquette pour une année universitaire, choisie en haut de la page. Elle est présentée niveau par niveau, puis période par période.</p><ol><li><strong>Ajouter une UE</strong> dans la période voulue : un nom, un code facultatif, et si elle est <strong>optionnelle</strong> (proposée au choix).</li><li>Dans l&#39;UE, <strong>Ajouter un EC</strong> : son nom, ses <strong>crédits</strong>, son <strong>coefficient</strong> (par défaut égal aux crédits) et son volume horaire en CM, TD et TP.</li></ol><p>Les crédits sont portés par les EC : ceux d&#39;une UE sont la somme de ses EC, ils ne peuvent donc jamais se contredire.</p><p>Une UE <strong>optionnelle</strong> est un choix, parmi quelques-unes ou librement dans l&#39;offre de la période : ses crédits <strong>complètent</strong> ceux des UE obligatoires jusqu&#39;au total de la période. Avec 24 crédits obligatoires, chaque étudiant choisit 6 crédits d&#39;options pour arriver à 30.</p><div class="tip custom-block"><p class="custom-block-title">Le compteur de crédits</p><p>Chaque période affiche ses crédits face à ce qu&#39;elle doit porter. Sans options, par exemple <strong>28 / 30 crédits</strong>. Avec des options, <strong>24 / 30 crédits obligatoires</strong>, suivi de ce qui reste à compléter et des crédits proposés : « 6 à compléter en options, sur 12 crédits proposés ». Le compteur passe au vert quand l&#39;offre permet d&#39;arriver au compte.</p></div><p>Les flèches réordonnent les UE d&#39;une période et les EC d&#39;une UE.</p><h2 id="une-maquette-par-annee" tabindex="-1">Une maquette par année <a class="header-anchor" href="#une-maquette-par-annee" aria-label="Permalink to &quot;Une maquette par année&quot;">​</a></h2><p>Chaque année universitaire a sa propre maquette. Modifier celle de cette année ne change jamais ce qu&#39;a suivi une promotion précédente.</p><p>Une nouvelle année démarre vide. ERA vous propose alors de <strong>reprendre la maquette de l&#39;année précédente</strong> en un clic : elle est copiée telle quelle, vous l&#39;ajustez ensuite. L&#39;ancienne reste intacte, et une année qui a déjà une maquette n&#39;est jamais écrasée.</p><p>Quand une année scolaire est <strong>clôturée</strong>, sa maquette l&#39;est aussi : elle reste consultable mais ne peut plus être modifiée.</p><h2 id="les-promotions" tabindex="-1">Les promotions <a class="header-anchor" href="#les-promotions" aria-label="Permalink to &quot;Les promotions&quot;">​</a></h2><p>Une <strong>promotion</strong> (par exemple « L1 Informatique 2026-2027 ») est une classe d&#39;un département universitaire. Lorsque vous créez une classe dans un tel département, ERA demande la <strong>filière</strong> qu&#39;elle suit, puis son <strong>niveau</strong>, choisi parmi ceux de la filière.</p><p>Une promotion n&#39;a ni bulletins, ni décisions de fin d&#39;année, ni réinscription en masse : ces écrans du scolaire l&#39;ignorent. Ses étudiants progresseront sur leurs crédits, validés par le jury de la filière.</p><p>Les étudiants y entrent par une <a href="/era-guide/guide/secretariat/candidatures.html#une-candidature-a-l-universite">candidature</a> qui vise la filière et le niveau.</p><h2 id="l-admission-selective" tabindex="-1">L&#39;admission sélective <a class="header-anchor" href="#l-admission-selective" aria-label="Permalink to &quot;L&#39;admission sélective&quot;">​</a></h2><p>Une filière peut recruter sur dossier : médecine, écoles d&#39;ingénieurs, masters à capacité limitée. Dans sa fiche, cochez <strong>Admission sélective</strong>, puis :</p><ul><li>fixez les <strong>places par niveau d&#39;entrée</strong>, offertes chaque année (laissez vide pour ne pas limiter un niveau) ;</li><li>désignez la <strong>commission d&#39;admission</strong>. Comme les responsables de filière, ses membres gardent leur rôle habituel et reçoivent en plus <strong>Supérieur → Admissions</strong>, limité aux filières dont ils font partie.</li></ul><p>Les candidatures à cette filière passent alors devant la commission avant toute inscription. Le formulaire prévient le candidat que son dossier sera examiné.</p><h3 id="decider-des-candidatures" tabindex="-1">Décider des candidatures <a class="header-anchor" href="#decider-des-candidatures" aria-label="Permalink to &quot;Décider des candidatures&quot;">​</a></h3><p><strong>Supérieur → Admissions</strong> liste les filières sélectives, niveau par niveau : places prises, dossiers à examiner, liste d&#39;attente, pour l&#39;année choisie en haut de la page. Le tableau de bord signale aussi aux membres de la commission les dossiers qui les attendent.</p><p>Un niveau ouvre le bureau de la commission. Les dossiers à examiner viennent d&#39;abord, dans l&#39;ordre d&#39;arrivée, puis les admis, la liste d&#39;attente dans l&#39;ordre de vos décisions, les inscrits et les refusés. Les pièces jointes s&#39;ouvrent depuis la ligne du candidat.</p><p>Le bouton <strong>Décider</strong> propose :</p><ul><li><strong>Admettre</strong> : le candidat prend une place. Quand toutes les places du niveau sont prises, ERA refuse l&#39;admission : placez-le en liste d&#39;attente ou augmentez le nombre de places ;</li><li><strong>Placer en liste d&#39;attente</strong> ;</li><li><strong>Refuser</strong>, avec un motif ;</li><li><strong>Remettre à examiner</strong>.</li></ul><p>Une note facultative accompagne la décision ; le secrétariat la voit, pas le candidat. Une décision reste modifiable jusqu&#39;à l&#39;inscription : si un admis se désiste, refusez-le avec le motif « désistement » et admettez le premier de la liste d&#39;attente.</p><p>Le secrétariat inscrit ensuite les admis dans une promotion de la filière, du niveau et de l&#39;année demandés.</p><h2 id="l-inscription-pedagogique" tabindex="-1">L&#39;inscription pédagogique <a class="header-anchor" href="#l-inscription-pedagogique" aria-label="Permalink to &quot;L&#39;inscription pédagogique&quot;">​</a></h2><p>Le bouton <strong>Promotions</strong> d&#39;une filière liste ses promotions pour l&#39;année choisie, avec leur effectif. Une promotion dont le niveau n&#39;a pas encore de maquette pour cette année est signalée.</p><p><strong>Inscriptions pédagogiques</strong> ouvre la page d&#39;une promotion :</p><ul><li>en haut, ses UE période par période, obligatoires et optionnelles ;</li><li>en dessous, ses étudiants, avec pour chaque période leurs crédits et les UE optionnelles qu&#39;ils ont choisies.</li></ul><p>Chaque étudiant suit <strong>toutes les UE obligatoires</strong> de son niveau : rien à saisir pour elles, et une UE ajoutée à la maquette s&#39;applique à toute la promotion. Ses <strong>UE optionnelles</strong> se choisissent avec le bouton <strong>Options</strong> de sa ligne : cochez celles qu&#39;il suit, puis enregistrez. Elles complètent les crédits de chaque période : la fenêtre indique ce qui reste à choisir, et ERA refuse un choix qui dépasse le total. Dans la liste, une période complète s&#39;affiche en vert, par exemple <strong>30 / 30 crédits</strong>.</p><p>L&#39;administrateur et les responsables de la filière tiennent ces inscriptions. Une fois l&#39;année clôturée, elles ne changent plus.</p>',44)])])}const g=s(r,[["render",a]]);export{m as __pageData,g as default};
